/**
 * Writes src/ts/exports.ts from the C exports of src/cpp, so that a call from
 * TypeScript with the wrong number of arguments does not compile.
 */
import fs from "fs";
import path from "path";

import { PackageRoot } from "./skia";

const Sources = path.join(PackageRoot, "src", "cpp");
const Output = path.join(PackageRoot, "src", "ts", "exports.ts");

// A return type, a name and parameters, after EMSCRIPTEN_KEEPALIVE.
const Export = /EMSCRIPTEN_KEEPALIVE\s+([^;{}()]*?)\b(sk_\w+)\s*\(([^)]*)\)/g;

export const generateExports = () => {
  const lines = [
    "// Generated by scripts/generate-exports.ts from the exports of src/cpp.",
    "// Do not edit: change the C++ and run `yarn generate-exports`.",
    "",
    "/**",
    " * The C exports of the module. Every argument and every result is a number:",
    " * a value, a pointer into wasm memory or a handle.",
    " */",
    "export interface Exports {",
  ];
  const files = fs
    .readdirSync(Sources)
    .filter((file) => file.endsWith(".cpp"))
    .sort();
  for (const file of files) {
    const source = fs.readFileSync(path.join(Sources, file), "utf8");
    lines.push(`  // ${file}`);
    for (const [, result, name, parameters] of source.matchAll(Export)) {
      const names = parameters
        .split(",")
        .map((parameter) => parameter.trim())
        .filter((parameter) => parameter !== "" && parameter !== "void")
        .map((parameter) => /(\w+)$/.exec(parameter)![1]);
      const type = result.trim() === "void" ? "void" : "number";
      const typed = names.map((parameter) => `${parameter}: number`);
      const line = `  _${name}(${typed.join(", ")}): ${type};`;
      if (line.length <= 80) {
        lines.push(line);
      } else {
        // The way Prettier breaks a signature that does not fit.
        lines.push(
          `  _${name}(`,
          ...typed.map(
            (parameter, i) =>
              `    ${parameter}${i < typed.length - 1 ? "," : ""}`
          ),
          `  ): ${type};`
        );
      }
    }
  }
  lines.push("}", "");
  const declarations = lines.join("\n");
  // Left alone when up to date, so that it does not look modified to a build.
  if (
    !fs.existsSync(Output) ||
    fs.readFileSync(Output, "utf8") !== declarations
  ) {
    fs.writeFileSync(Output, declarations);
  }
  return Output;
};

if (require.main === module) {
  console.log(`✅ ${path.relative(PackageRoot, generateExports())}`);
}
